<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/includes/auth.php';$db=db();$e=fn($v)=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');$project=(int)($_GET['project_id']??$_POST['project_id']??0);if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['task'])){$q=$db->prepare('INSERT INTO project_tasks(project_id,assigned_staff_id,title,description,priority,status,start_date,due_date,estimated_hours) VALUES(?,?,?,?,?,?,?,?,?)');$q->execute([$project,$_POST['assigned_staff_id']?:null,trim($_POST['title']),trim($_POST['description']??''),$_POST['priority'],$_POST['status'],$_POST['start_date']?:null,$_POST['due_date']?:null,(float)($_POST['estimated_hours']??0)]);header('Location: project-tasks.php?project_id='.$project);exit;}if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['time'])){$q=$db->prepare('INSERT INTO time_entries(task_id,project_id,staff_id,work_date,hours,billable,hourly_rate,description,status) VALUES(?,?,?,?,?,?,?,?,?)');$q->execute([$_POST['task_id']?:null,$project,(int)$_POST['staff_id'],$_POST['work_date'],(float)$_POST['hours'],isset($_POST['billable'])?1:0,(float)($_POST['hourly_rate']??0),trim($_POST['time_description']??''),'submitted']);header('Location: project-tasks.php?project_id='.$project);exit;}$staff=$db->query("SELECT id,first_name,last_name FROM staff_members WHERE employment_status='active' ORDER BY first_name")->fetchAll();$q=$db->prepare('SELECT t.*,CONCAT(s.first_name," ",s.last_name) staff_name FROM project_tasks t LEFT JOIN staff_members s ON s.id=t.assigned_staff_id WHERE t.project_id=? ORDER BY t.sort_order,t.due_date,t.id');$q->execute([$project]);$tasks=$q->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Project Tasks</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-4"><h1 class="h3">Project Tasks & Time</h1><div class="card mb-4"><div class="card-body"><form method="post" class="row g-2"><input type="hidden" name="project_id" value="<?=$project?>"><input type="hidden" name="task" value="1"><div class="col-md-4"><input class="form-control" name="title" placeholder="Task title" required></div><div class="col-md-2"><select class="form-select" name="assigned_staff_id"><option value="">Unassigned</option><?php foreach($staff as $s):?><option value="<?=$s['id']?>"><?=$e($s['first_name'].' '.$s['last_name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><select class="form-select" name="priority"><option>low</option><option selected>medium</option><option>high</option><option>urgent</option></select></div><div class="col-md-2"><select class="form-select" name="status"><option>todo</option><option>in_progress</option><option>blocked</option><option>completed</option></select></div><div class="col-md-2"><input class="form-control" type="number" step="0.25" name="estimated_hours" placeholder="Hours"></div><div class="col-md-4"><input class="form-control" type="date" name="start_date"></div><div class="col-md-4"><input class="form-control" type="date" name="due_date"></div><div class="col-md-4"><input class="form-control" name="description" placeholder="Description"></div><div class="col-12"><button class="btn btn-dark">Create Task</button></div></form></div></div><div class="card"><div class="card-body"><table class="table"><thead><tr><th>Task</th><th>Staff</th><th>Priority</th><th>Status</th><th>Due</th><th>Est. Hours</th></tr></thead><tbody><?php foreach($tasks as $t):?><tr><td><?=$e($t['title'])?></td><td><?=$e($t['staff_name'])?></td><td><?=$e($t['priority'])?></td><td><?=$e($t['status'])?></td><td><?=$e($t['due_date'])?></td><td><?=$e($t['estimated_hours'])?></td></tr><?php endforeach;?></tbody></table><hr><h2 class="h5">Log Time</h2><form method="post" class="row g-2"><input type="hidden" name="project_id" value="<?=$project?>"><input type="hidden" name="time" value="1"><div class="col-md-3"><select class="form-select" name="staff_id" required><?php foreach($staff as $s):?><option value="<?=$s['id']?>"><?=$e($s['first_name'].' '.$s['last_name'])?></option><?php endforeach;?></select></div><div class="col-md-3"><select class="form-select" name="task_id"><option value="">General project time</option><?php foreach($tasks as $t):?><option value="<?=$t['id']?>"><?=$e($t['title'])?></option><?php endforeach;?></select></div><div class="col-md-2"><input class="form-control" type="date" name="work_date" value="<?=date('Y-m-d')?>" required></div><div class="col-md-2"><input class="form-control" type="number" step="0.25" name="hours" placeholder="Hours" required></div><div class="col-md-2"><input class="form-control" type="number" step="0.01" name="hourly_rate" placeholder="Rate"></div><div class="col-md-8"><input class="form-control" name="time_description" placeholder="Work performed"></div><div class="col-md-2 form-check mt-2"><input class="form-check-input" type="checkbox" name="billable" checked> Billable</div><div class="col-md-2"><button class="btn btn-outline-dark">Log Time</button></div></form></div></div></main></body></html>